import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring for standard 2D vector animation

const { fontFamily: oswaldFamily } = loadOswald();



export type AbsoluteMustHavesProps = Record<string, any>;

const AbsoluteMustHaves: React.FC<AbsoluteMustHavesProps> = ({
  backgroundColor = "#0A192F",
  transparentBackground = false,
  durationInSeconds = 5,
  textLine1 = "ABSOLUTE",
  textLine2 = "MUST HAVES",
  accentColor = "#F3B61F",
  clipboardShadowColor = "#162D55",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timing ---
  const text1Enter = spring({ frame: frame - 12, fps, config: { damping: 14 } });
  const text1Opacity = interpolate(text1Enter, [0, 1], [0, 1], { extrapolateLeft: "clamp" });
  const text1Y = interpolate(text1Enter, [0, 1], [50 * s, 0], { extrapolateLeft: "clamp" });

  const text2Enter = spring({ frame: frame - 18, fps, config: { damping: 14 } });
  const text2Opacity = interpolate(text2Enter, [0, 1], [0, 1], { extrapolateLeft: "clamp" });
  const text2Y = interpolate(text2Enter, [0, 1], [50 * s, 0], { extrapolateLeft: "clamp" });

  const clipEnter = spring({ frame: frame - 25, fps, config: { damping: 12 } });

  // --- Layout Dimensions ---
  const gap = 80 * s;
  const clipWidth = 240 * s;
  const clipHeight = clipWidth * 1.3;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          width: "100%",
          height: "100%",
          alignItems: "center",
          justifyContent: "center",
          gap: `${gap}px`,
          padding: `${50 * s}px`,
          transition: "none",
        }}
      >
        {/* TEXT STACK */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            justifyContent: "center",
            fontFamily: oswaldFamily,
            fontWeight: 700,
            lineHeight: 0.95,
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: `${200 * s}px`,
              color: "#FFFFFF",
              transform: `translateY(${text1Y}px)`,
              opacity: text1Opacity,
              transition: "none",
            }}
          >
            {textLine1}
          </div>
          <div
            style={{
              fontSize: `${180 * s}px`,
              color: accentColor,
              transform: `translateY(${text2Y}px)`,
              opacity: text2Opacity,
              marginTop: `${-10 * s}px`,
              transition: "none",
            }}
          >
            {textLine2}
          </div>
        </div>

        {/* CLIPBOARD */}
        <div
          style={{
            transform: `scale(${Math.max(0, clipEnter)}) rotate(${interpolate(clipEnter, [0, 1], [15, 0])}deg)`,
            opacity: clipEnter > 0 ? 1 : 0,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          <svg
            width={clipWidth}
            height={clipHeight}
            viewBox="0 0 240 312"
            style={{ overflow: "visible" }}
          >
            {/* Backing Shadow */}
            <rect x="20" y="20" width="200" height="280" rx="16" fill={clipboardShadowColor} />
            
            {/* Paper */}
            <rect x="0" y="40" width="200" height="272" rx="12" fill="#FFFFFF" />

            {/* Clip Hardware */}
            <rect x="60" y="20" width="80" height="28" rx="6" fill={accentColor} />
            <path d="M 80 20 C 80 -8, 120 -8, 120 20 Z" fill={accentColor} />
            <circle cx="100" cy="8" r="10" fill={clipboardShadowColor} />

            {/* Rows (Checkboxes + Lines) */}
            {[0, 1, 2, 3].map((i) => {
              const rowStart = 40 + i * 4;
              const rowScale = spring({ frame: frame - rowStart, fps, config: { damping: 14 } });
              const tickDraw = spring({ frame: frame - (rowStart + 4), fps, config: { damping: 12 } });
              
              const y = 90 + i * 50;
              const isVisible = rowScale > 0.01;

              return isVisible ? (
                <g
                  key={i}
                  style={{
                    transform: `scale(${rowScale})`,
                    transformOrigin: `24px ${y + 12}px`,
                    opacity: rowScale,
                    transition: "none",
                  }}
                >
                  {/* Yellow Box */}
                  <rect x="24" y={y} width="28" height="28" rx="6" fill={accentColor} />
                  
                  {/* Black Tick */}
                  <path
                    d={`M ${30} ${y + 14} L ${36} ${y + 20} L ${46} ${y + 8}`}
                    fill="none"
                    stroke="#1C2E4A"
                    strokeWidth="5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    pathLength="1"
                    strokeDasharray="1"
                    strokeDashoffset={interpolate(tickDraw, [0, 1], [1, 0])}
                  />
                  
                  {/* Grey/Blue Line */}
                  <rect x="70" y={y + 10} width="100" height="8" rx="4" fill={clipboardShadowColor} />
                </g>
              ) : null;
            })}
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

